function debounce(fn, delay) {
  let timer;
  return function() {
    clearTimeout(timer);
    timer = setTimeout(() => fn.apply(this, arguments), delay);
  };
}

def add_zero(array):
    zero_indices = [i for i, x in enumerate(array) if x == 0]
    for index in zero_indices:
        array.insert(index + 1, 0)
    return array

